using System.ComponentModel;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class FetchDataTool
{
    [McpServerTool("fetch_data"), Description("Fetches data from an external API endpoint.")]
    public static async Task<string> FetchDataAsync(
        IHttpClientFactory httpClientFactory,
        ILogger<FetchDataTool> logger,
        [Description("The API path to query (e.g. /users/1)")] string path)
    {
        logger.LogInformation("Fetching data from path: {Path}", path);

        var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(path);

        response.EnsureSuccessStatusCode();
        var content = await response.Content.ReadAsStringAsync();

        logger.LogInformation("Received {Length} chars from API", content.Length);
        return content;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Generates a summarization prompt for the given text.")]
    public static IList<McpServerPromptMessage> Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Desired summary style: brief, detailed, or bullet-points")] string style = "brief")
    {
        var systemMessage = style switch
        {
            "detailed" => "You are an expert summarizer. Provide a comprehensive summary preserving key details.",
            "bullet-points" => "You are an expert summarizer. Summarize the text as concise bullet points.",
            _ => "You are an expert summarizer. Provide a brief, concise summary in 2-3 sentences."
        };

        return
        [
            new McpServerPromptMessage
            {
                Role = Role.Assistant,
                Content = new Content { Text = systemMessage, Type = "text" }
            },
            new McpServerPromptMessage
            {
                Role = Role.User,
                Content = new Content { Text = $"Please summarize the following:\n\n{text}", Type = "text" }
            }
        ];
    }
}

